10	import { spacing } from 'app/theme/foundation/spacing';
11	import { OPACITY_ICON_DISABLED } from 'app/components/ui-kits/zimmCartItemShared';
12	
13	// ZimmIcon imports the base SFCC icons barrel, which throws under Vitest (SVG imports resolve to
14	// raw path strings in this environment, not components) — see testing.md's Known gap. ZimmButton
15	// itself renders for real in every test below (not mocked): only its own leaf icon is stubbed, so
16	// the real ariaDisabled/onClick-suppression wiring this suite depends on is genuinely exercised
17	// end-to-end, not assumed from ZimmButton's own separate test suite.
18	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
19	
20	const DECREMENT_NAME = 'Decrease quantity';
21	const INCREMENT_NAME = 'Increase quantity';
22	
23	const renderStepper = (props: Partial<React.ComponentProps<typeof ZimmQuantityStepper>> = {}) => {
24	  const onDecrement = vi.fn();
25	  const onIncrement = vi.fn();
26	  render(
27	    <IntlProvider locale="en">
28	      <ChakraProvider theme={theme}>
29	        <ZimmQuantityStepper quantity={3} max={5} onDecrement={onDecrement} onIncrement={onIncrement} {...props} />
30	      </ChakraProvider>
31	    </IntlProvider>,
32	  );
33	  return { onDecrement, onIncrement };
34	};
35	
36	describe('ZimmQuantityStepper — quantity = 1 (min boundary, State 1)', () => {
37	  test('decrement button carries aria-disabled="true"', () => {
38	    renderStepper({ quantity: 1 });
39	    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
40	  });
41	
42	  test('clicking decrement at quantity 1 does NOT call onDecrement — quantity stays 1', () => {
43	    const { onDecrement } = renderStepper({ quantity: 1 });
44	    fireEvent.click(screen.getByRole('button', { name: DECREMENT_NAME }));
45	    expect(onDecrement).not.toHaveBeenCalled();
