96	describe('ZimmQuantityStepper — isUnavailable (State 4, fully OOS/unavailable)', () => {
97	  test('both buttons carry aria-disabled="true", even mid-range (not just at a quantity bound)', () => {
98	    renderStepper({ quantity: 3, max: 5, isUnavailable: true });
99	    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
100	    expect(screen.getByRole('button', { name: INCREMENT_NAME })).toHaveAttribute('aria-disabled', 'true');
